// The real generator registry `pnpm check:generated` runs (TASKS.md 1.3.c, 23.1.c). Every file below
// is one nobody hand-edits (AGENTS.md); each is regenerated by its CMS package's own script in one
// environment with no DATABASE_URL (`contexts.mjs`) and compared with the committed file, for each
// CMS (`CMSES`: today's `@engine/cms` and the shop's `@engine/cms-shop`):
//
//   payload-types      `generate:types`, equal to the CMS's committed payload-types.ts
//   importmap.<app>    `generate:importmap <app>` of the CMS serving the app, equal to the app's
//                      committed importMap.js — for each app that mounts the admin; a component
//                      missing from the map renders as nothing, with no error (CARRY-OVER.md §4)
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { availableParallelism } from 'node:os'
import { join } from 'node:path'

import { CMSES, cmsScripts, limiter } from './cms-scripts.mjs'
import { NothingToCheckYet } from './config-drift.mjs'

/** Where an app mounts Payload's admin, and its import map (the CMS script's own ADMIN_PATH). */
export const ADMIN_PATH = 'src/app/(payload)/admin'
const importMapPath = (app) => `engine/apps/${app}/${ADMIN_PATH}/importMap.js`

/** Every app under engine/apps/ with an admin mount, sorted. */
export function appsWithAdminMount(repoRoot) {
  const appsDir = join(repoRoot, 'engine', 'apps')
  if (!existsSync(appsDir)) return []
  return readdirSync(appsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((app) => existsSync(join(appsDir, app, ...ADMIN_PATH.split('/'))))
    .sort()
}

function readOrNull(file) {
  try {
    return readFileSync(file, 'utf8')
  } catch {
    return null
  }
}

/**
 * The generators for `repoRoot`: each CMS's `payload-types.ts` (`CMSES`), and each app's import map
 * from the CMS that serves it. `scripts` is injectable so a test can stand in for Payload: one
 * fixture CMS serving every app.
 */
export function realGenerators(repoRoot, { scripts } = {}) {
  const bounded = limiter(Math.max(1, Math.min(4, availableParallelism() - 1)))
  const cmses = scripts
    ? [{ ...CMSES[0], owns: () => true, scripts }]
    : CMSES.map((cms) =>
        Object.assign({}, cms, {
          scripts: cmsScripts(repoRoot, { pkg: cms.pkg, typesPath: cms.typesPath, bounded }),
        }),
      )
  const generators = cmses.map((cms) => ({
    name: cms.name,
    committedPath: cms.typesPath,
    required: true,
    regenerate: () => cms.scripts.payloadTypes(),
  }))

  const apps = appsWithAdminMount(repoRoot)
  if (apps.length === 0) {
    generators.push({
      name: 'importmap',
      committedPath: importMapPath('<app>'),
      regenerate: () => {
        throw new NothingToCheckYet(
          `no app under engine/apps/* mounts the admin at ${ADMIN_PATH}, so generate:importmap is skipped — it would exit 1 with "no admin mount"`,
        )
      },
    })
  }
  for (const app of apps) {
    const cms = cmses.find((each) => each.owns(app))
    const committedPath = importMapPath(app)
    const committedAbs = join(repoRoot, ...committedPath.split('/'))
    // Read before the run: the script rewrites this file while it runs (and puts it back).
    const committed = readOrNull(committedAbs)
    generators.push({
      name: `importmap.${app}`,
      committedPath,
      required: true,
      regenerate: () => cms.scripts.importMap(app, committedAbs),
      expected: () => committed,
    })
  }
  return generators
}
